/**
 * Unit tests for DateTimeZone#getOffsetFromLocal.
 * Since DateTimeZone is an abstract class with complex logic depending on internal 
 * transition calculations, we use a Mockito spy on a subclass to control the 
 * behavior of abstract methods like getOffset, nextTransition, and previousTransition.
 */
public class DateTimeZone_getOffsetFromLocal_TriageGen1Test {

    /**
     * A concrete implementation of DateTimeZone for testing purposes.
     */
    private static class TestDateTimeZone extends DateTimeZone {
        protected TestDateTimeZone() {
            super("TestZone");
        }

        @Override
        public int getOffset(long instant) {
            return 0; // Default, will be mocked
        }

        @Override
        public String getNameKey(long instant) {
            return "Test";
        }

        @Override
        public boolean isStandardOffset(long instant) {
            return true;
        }

        @Override
        public long nextTransition(long instant) {
            return 0; // Default, will be mocked
        }

        @Override
        public long previousTransition(long instant) {
            return 0; // Default, will be mocked
        }

        @Override
        public int getStandardOffset(long instant) {
            return 0;
        }

        @Override
        public boolean isFixed() {
            return false;
        }
    }

    @Test
    public void testGetOffsetFromLocal_SimpleCase() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 1000L;

        // Scenario: offsetLocal == offsetAdjusted
        when(zone.getOffset(instantLocal)).thenReturn(3600);
        when(zone.getOffset(instantLocal - 3600)).thenReturn(3600);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(3600, result);
    }

    @Test
    public void testGetOffsetFromLocal_DSTGap_NegativeDifference() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 2000L;

        // Scenario: offsetLocal != offsetAdjusted AND (offsetLocal - offsetAdjusted) < 0
        // offsetLocal = 10, offsetAdjusted = 20 -> diff = -10
        when(zone.getOffset(instantLocal)).thenReturn(10);
        when(zone.getOffset(instantLocal - 10)).thenReturn(20);

        // Branch: nextLocal != nextAdjusted
        when(zone.nextTransition(instantLocal - 20)).thenReturn(3000L); // nextLocal (instantAdjusted is 1990)
        when(zone.nextTransition(instantLocal - 20)).thenReturn(4000L); // nextAdjusted (instantLocal - offsetAdjusted is 1980)
        // Note: in the code nextLocal = nextTransition(instantAdjusted) 
        // where instantAdjusted = instantLocal - offsetLocal.

        // Re-aligning mock to match exact code logic:
        // instantAdjusted = 2000 - 10 = 1990
        // nextLocal = nextTransition(1990)
        // nextAdjusted = nextTransition(2000 - 20) = nextTransition(1980)
        when(zone.nextTransition(1990L)).thenReturn(2500L);
        when(zone.nextTransition(1980L)).thenReturn(3500L);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(10, result);
    }

    @Test
    public void testGetOffsetFromLocal_DSTGap_NegativeDifference_EqualNextTransition() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 2000L;

        when(zone.getOffset(instantLocal)).thenReturn(10);
        when(zone.getOffset(instantLocal - 10)).thenReturn(20);

        // if (nextLocal == nextAdjusted) -> returns offsetAdjusted
        when(zone.nextTransition(1990L)).thenReturn(2500L);
        when(zone.nextTransition(1980L)).thenReturn(2500L);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(20, result);
    }

    @Test
    public void testGetOffsetFromLocal_PositiveOffset_WithPrevTransition() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 5000L;

        // Scenario: offsetLocal == offsetAdjusted AND offsetLocal > 0
        // offsetLocal = 3600
        when(zone.getOffset(instantLocal)).thenReturn(3600);
        when(zone.getOffset(instantLocal - 3600)).thenReturn(3600);

        // prev < instantAdjusted
        long instantAdjusted = 5000L - 3600L; // 1400
        long prev = 1000L;
        when(zone.previousTransition(instantAdjusted)).thenReturn(prev);

        // offsetPrev = 7200, diff = 7200 - 3600 = 3600
        when(zone.getOffset(prev)).thenReturn(7200);

        // instantAdjusted - prev <= diff => 1400 - 1000 <= 3600 (True)
        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(7200, result);
    }

    @Test
    public void testGetOffsetFromLocal_PositiveOffset_PrevTransitionConditionFalse() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 5000L;

        when(zone.getOffset(instantLocal)).thenReturn(3600);
        when(zone.getOffset(instantLocal - 3600)).thenReturn(3600);

        long instantAdjusted = 1400L;
        long prev = 1300L;
        when(zone.previousTransition(instantAdjusted)).thenReturn(prev);

        // offsetPrev = 3700, diff = 3700 - 3600 = 100
        // instantAdjusted - prev = 1400 - 1300 = 100
        // 100 <= 100 is True. Let's make it False.
        when(zone.getOffset(prev)).thenReturn(3650); 
        // diff = 3650 - 3600 = 50.
        // 100 <= 50 is False.

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(3600, result);
    }

    @Test
    public void testGetOffsetFromLocal_PositiveOffset_NoPrevTransition() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 5000L;

        when(zone.getOffset(instantLocal)).thenReturn(3600);
        when(zone.getOffset(instantLocal - 3600)).thenReturn(3600);

        // prev >= instantAdjusted
        long instantAdjusted = 1400L;
        when(zone.previousTransition(instantAdjusted)).thenReturn(1500L);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(3600, result);
    }

    @Test
    public void testGetOffsetFromLocal_NonPositiveOffset_NoPrevTransition() {
        TestDateTimeZone zone = spy(new TestDateTimeZone());
        long instantLocal = 5000L;

        // offsetLocal <= 0
        when(zone.getOffset(instantLocal)).thenReturn(-3600);
        when(zone.getOffset(instantLocal - (-3600))).thenReturn(-3600);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(-3600, result);
    }
}
